const webhookItem = $("Webhook (Receive Form)").first().json;
const webhookData = webhookItem.body || webhookItem;
const weatherData = $input.first().json;

const city = webhookData.city || 'Destination';
const country = webhookData.country || '';
const startDate = webhookData.startDate || new Date().toISOString().split('T')[0];
const endDate = webhookData.endDate || startDate;

const WMO_MAP = {
  0: { emoji: '☀️', desc: 'Clear sky' },
  1: { emoji: '🌤️', desc: 'Mainly clear' },
  2: { emoji: '⛅', desc: 'Partly cloudy' },
  3: { emoji: '☁️', desc: 'Overcast' },
  45: { emoji: '🌫️', desc: 'Foggy' },
  48: { emoji: '🌫️', desc: 'Depositing rime fog' },
  51: { emoji: '🌦️', desc: 'Light drizzle' },
  53: { emoji: '🌦️', desc: 'Moderate drizzle' },
  55: { emoji: '🌧️', desc: 'Dense drizzle' },
  61: { emoji: '🌧️', desc: 'Slight rain' },
  63: { emoji: '🌧️', desc: 'Moderate rain' },
  65: { emoji: '🌧️', desc: 'Heavy rain' },
  71: { emoji: '🌨️', desc: 'Light snow' },
  73: { emoji: '🌨️', desc: 'Moderate snow' },
  75: { emoji: '❄️', desc: 'Heavy snow' },
  80: { emoji: '🌦️', desc: 'Light rain showers' },
  81: { emoji: '🌧️', desc: 'Moderate rain showers' },
  82: { emoji: '⛈️', desc: 'Violent rain showers' },
  95: { emoji: '⛈️', desc: 'Thunderstorm' },
  96: { emoji: '⛈️', desc: 'Thunderstorm with hail' },
  99: { emoji: '⛈️', desc: 'Thunderstorm with heavy hail' }
};

const daily = weatherData.daily || {};
const timeArr = daily.time || [startDate];
const codeArr = daily.weather_code || [0];
const maxArr = daily.temperature_2m_max || [24];
const minArr = daily.temperature_2m_min || [16];

const dailyForecasts = timeArr.map((dateStr, idx) => {
  const code = codeArr[idx] !== undefined ? codeArr[idx] : 0;
  const info = WMO_MAP[code] || { emoji: '🌤️', desc: 'Variable' };
  return {
    date: dateStr,
    temp_max: Math.round(maxArr[idx] !== undefined ? maxArr[idx] : 24),
    temp_min: Math.round(minArr[idx] !== undefined ? minArr[idx] : 16),
    emoji: info.emoji,
    description: info.desc
  };
});

const forecastSummary = dailyForecasts.map(d => 
  `- ${d.date}: ${d.description} ${d.emoji}, High ${d.temp_max}°C, Low ${d.temp_min}°C`
).join('\n');

const systemPrompt = `You are a world-class travel curator. Create an authentic, day-by-day itinerary formatted as JSON.\n\nSTRICT RULES:\n1. FORBIDDEN GENERIC FILLER: NEVER use generic placeholders like 'Visit Museum', 'Local Museum', 'Attend a Workshop', 'Cooking Workshop', 'Pottery Workshop', 'Explore the City', 'Local Cuisine', or 'Sunset Views'.\n2. REAL LANDMARKS: Every single activity title MUST be an ACTUAL, RENOWNED, SPECIFIC FAMOUS PLACE or landmark in or near ${city}.\n3. PROPER CONTEXT: Describe the genuine historical, cultural, or architectural context of that specific place and explain why it fits today's weather.\n4. Return STRICT JSON format:\n{\n  "packing_list": [\n    { "icon": "☔", "label": "Compact Umbrella" },\n    { "icon": "👟", "label": "Comfortable Walking Shoes" },\n    { "icon": "🕶️", "label": "Sunscreen & Sunglasses" }\n  ],\n  "itinerary": [\n    {\n      "date": "YYYY-MM-DD",\n      "dayName": "Monday",\n      "weather": { "emoji": "☀️", "temp_max": 25, "temp_min": 15, "description": "Clear sky" },\n      "activities": [\n        { "time": "Morning", "title": "Actual Famous Landmark", "description": "Authentic contextual description...", "category": "outdoor" },\n        { "time": "Late Morning", "title": "Actual Historic Palace/Museum", "description": "...", "category": "culture" },\n        { "time": "Afternoon", "title": "Famous Market/Dining Landmark", "description": "...", "category": "dining" },\n        { "time": "Evening", "title": "Famous Waterfront/Observatory", "description": "...", "category": "relax" }\n      ]\n    }\n  ]\n}\n5. Adapt activities to weather: indoor cultural landmarks for rain/snow, outdoor monuments and parks for clear/sunny days.`;

const userPrompt = `Destination: ${city}, ${country}\nDates: ${startDate} to ${endDate}\n\nDaily Weather Forecast:\n${forecastSummary}`;

const groqApiKey = $env.GROQ_API_KEY || 'YOUR_GROQ_API_KEY';

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.groq.com/openai/v1/chat/completions',
  headers: {
    'Authorization': `Bearer ${groqApiKey}`,
    'Content-Type': 'application/json'
  },
  body: {
    model: 'openai/gpt-oss-120b',
    response_format: { type: 'json_object' },
    temperature: 0.5,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ]
  },
  json: true
});

let content = '';
if (response && response.choices && response.choices[0] && response.choices[0].message) {
  content = response.choices[0].message.content;
} else if (typeof response === 'string') {
  content = response;
}

let parsed = null;
try {
  parsed = JSON.parse(content);
} catch (e) {
  const clean = content.replace(/```json/g, '').replace(/```/g, '').trim();
  try { parsed = JSON.parse(clean); } catch (err) {}
}

if (!parsed || !parsed.itinerary) {
  throw new Error('Groq AI API failed to return a valid itinerary structure.');
}

if (Array.isArray(parsed.itinerary)) {
  parsed.itinerary = parsed.itinerary.map((item, idx) => {
    const fallbackForecast = dailyForecasts[idx] || {};
    if (!item.weather || !item.weather.temp_max) {
      item.weather = {
        emoji: fallbackForecast.emoji || '🌤️',
        temp_max: fallbackForecast.temp_max || 24,
        temp_min: fallbackForecast.temp_min || 16,
        description: fallbackForecast.description || 'Forecast'
      };
    }
    return item;
  });
}

return [{ json: parsed }];
